  const copy={en:{title:'Software I | modular workflow',current:'Current event-routing modules',future:'Reserved Software II interfaces',inflow:'1. Inflow boundary',storage:'2. Storage–level state',routing:'3. Routing core',outlet:'4. Outlet hydraulics',optimization:'5. Constrained design optimization',evaluation:'6. Evaluation & decision support',upstream:'Upstream rainfall–runoff',multi:'Multiple inflows / catchments',downstream:'Continuous detention-chain',planned:'Software II',pt:'Whole-system first-principles validation',steps:['Boundary flow Qin(t)','Mass conservation: dS/dt = Qin − Qout','State relation: H = H(S)','Outlet law and coefficients','Constraints, diagnostics, decision record'],scope:'Every active module is checked against the same physical contract. A warning identifies an incomplete boundary, state, outlet, coefficient source, or conservation record.'},zh:{title:'Software I｜模組化工作流程',current:'本研究 Software I 模組',future:'預留的 Software II 介面',inflow:'1. 入流邊界',storage:'2. 蓄水量—水位狀態',routing:'3. 路由演算核心',outlet:'4. 出口水理',optimization:'5. 受限設計最佳化',evaluation:'6. 評估與決策支援',upstream:'上游降雨—逕流',multi:'多入流／多集水區',downstream:'下游連續性滯洪池',planned:'Software II',pt:'全系統第一性原理檢核',steps:['邊界流量 Qin(t)','質量守恆：dS/dt = Qin − Qout','狀態關係：H = H(S)','出口定律與流量係數','限制、診斷與決策紀錄'],scope:'每一啟用模組均依相同物理契約檢核。警示表示邊界、狀態、出口、係數來源或守恆紀錄尚未完整。'}};
  const lang=()=>document.documentElement.lang==='zh-Hant'?'zh':'en';
