  function integrity(){const c=copy[lang()],steps=document.getElementById('principleSteps');if(!steps)return;const yes=id=>document.getElementById(id)?.checked;const row=[...document.querySelectorAll('#metricbody tr')].find(r=>/Mass-balance/.test(r.textContent)),residual=row?Number((row.cells[1]?.textContent||'').replace(/[^0-9+-.]/g,'')):NaN;const checks=[Number(document.getElementById('qp')?.value)>0&&Number(document.getElementById('dur')?.value)>0,document.getElementById('storageMode')?.value==='table'||Number(document.getElementById('area')?.value)>0,yes('weirOn')||yes('oriOn')||yes('riserOn'),document.getElementById('coeffMode')?.value!=='table'||(document.getElementById('coeffSource')?.value.trim()&&/^https?:\/\//.test(document.getElementById('coeffUrl')?.value.trim())),Number.isFinite(residual)&&Math.abs(residual)<=.5],ok=checks.every(Boolean);workspace.dataset.integrity=ok?'ok':'warn';document.getElementById('principleTitle').textContent=c.pt+(ok?' ✓':' ⚠');[...steps.children].forEach((e,i)=>e.classList.toggle('principle-pass',!!checks[i]));}
  const style=document.createElement('style');style.textContent=`.grid{grid-template-columns:270px minmax(0,1fr)!important;align-items:start}.module-nav{position:sticky;top:12px;padding:14px}.module-nav h2{font-size:17px;margin-bottom:16px}.module-caption{font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:.05em;color:#526a78;margin:12px 0 6px}.module-link{display:block;width:100%;text-align:left;border:1px solid #c7d7df;background:#fff;color:#102a43;padding:9px 10px;border-radius:5px;margin:5px 0;font:inherit;font-size:14px;cursor:pointer}.module-link:hover{border-color:#0b557d;background:#eaf4f8}.future-caption{margin-top:20px}.module-future{display:flex;justify-content:space-between;gap:5px;padding:8px 4px;border-bottom:1px solid #e1e9ed;color:#748692;font-size:13px}.module-future em{font-style:normal;font-size:11px;color:#8b98a1;white-space:nowrap}.module-workspace{min-width:0}.module-card{margin-top:18px;padding:14px;border:1px solid var(--module-line);border-left:6px solid var(--module);border-radius:7px;background:var(--module-bg)}.inflow-card{--module:#2563eb;--module-line:#bfd1dc;--module-bg:#f7faff}.storage-card{--module:#15803d;--module-line:#b9d8c4;--module-bg:#f5fcf7}.routing-card{--module:#7c3aed;--module-line:#d8c9f5;--module-bg:#faf8ff}.outlet-card{--module:#c2410c;--module-line:#f2c9b6;--module-bg:#fff9f5}.optimization-card{--module:#9a5a00;--module-line:#efd4a1;--module-bg:#fffaf0}.evaluation-card{--module:#0b557d;--module-line:#bfd1dc;--module-bg:#f6fbfd}.principle-contract{border:1px solid #bfd1dc;border-left:5px solid #0b557d;background:#f6fbfd;padding:12px;margin:0 0 16px}.principle-contract strong{display:block;color:#102a43;margin-bottom:8px}.principle-contract #principleSteps{display:flex;flex-wrap:wrap;gap:7px}.principle-contract span{background:#fff8e7;border:1px solid #f0cc81;border-radius:14px;padding:4px 8px;font-size:12px;color:#765111}.principle-contract span.principle-pass{background:#f0fdf4;border-color:#9bc8aa;color:#166534}.principle-contract b{display:inline-grid;place-items:center;width:16px;height:16px;border-radius:50%;background:currentColor;color:#fff;margin-right:5px;font-size:10px}.principle-contract p{font-size:12px;color:#526a78;margin:9px 0 0}.module-workspace[data-integrity="warn"] .principle-contract{border-left-color:#e79a17;background:#fffaf0}.module-flash{outline:3px solid #75b6d8;outline-offset:4px;border-radius:4px}@media(max-width:850px){.grid{grid-template-columns:1fr!important}.module-nav{position:static}.module-nav #moduleNavContent{display:grid;grid-template-columns:1fr 1fr;gap:5px}.module-nav h2,.module-nav p{grid-column:1/-1}.module-link{margin:0;font-size:13px}.module-future{display:none}}`;document.head.appendChild(style);renderNav();integrity();workspace.addEventListener('input',integrity);workspace.addEventListener('change',integrity);['run','optimize'].forEach(id=>document.getElementById(id)?.addEventListener('click',()=>setTimeout(integrity,0)));document.getElementById('lang')?.addEventListener('click',()=>setTimeout(()=>{renderNav();integrity();},0));
